"""Complete 24 original mood-disorder questions."""
from create_psych_mood_diagnosis import rows,q,DE,BP,CA,NI,ref
from qbank_authoring import finalize
NB=ref('NICE bipolar disorder management','https://www.nice.org.uk/guidance/cg185/chapter/recommendations')

q('An adult with less severe depression prefers a psychological approach and has no urgent safety concerns. Which initial strategy is consistent with NICE guidance?', 'Offer an appropriate evidence-based psychological intervention such as guided self-help or CBT with follow-up',[
 ('Start an antidepressant automatically irrespective of preference','Medication is not routinely required as first-line treatment for every less severe presentation.'),('Use antipsychotic monotherapy as the usual first treatment','This is not the standard approach to nonpsychotic less severe depression.'),('Provide no review because less severe depression cannot deteriorate','Monitoring, shared planning and reassessment remain important.')],
 'Match treatment intensity to need and preference','**Less severe depression has effective psychological treatment options.**',['Discuss the likely benefits, burdens and availability.','Medication can still be appropriate when preferred or indicated by the individual course.'],'**Agree goals and a review plan.**',['Assess impairment and safety at follow-up.','Escalate if symptoms persist or worsen.'],[['Initial choice','Shared decision'],['Psychological option','Evidence-based structured care'],['Follow-up','Response and safety review']],[DE],style='clinical_scenario')

q('A patient with severe depression refuses food and fluids because of depressive delusions and is becoming medically unstable. Which treatment warrants urgent specialist consideration for rapid response?', 'Electroconvulsive therapy',[
 ('Wait through several sequential antidepressant monotherapy trials before considering any rapid treatment','Life-threatening deterioration can justify earlier ECT consideration.'),('Psychological therapy alone despite progressive medical instability','Therapy is valuable but does not provide the required immediate biological treatment by itself.'),('Benzodiazepine monotherapy as definitive treatment of the depressive disorder','It does not adequately treat the underlying severe psychotic depression.')],
 'Urgency changes the treatment sequence','**ECT is an important option when severe depression requires a rapid response.**',['Assess medical stabilization, anesthesia risk and consent/capacity.','Discuss potential benefits and cognitive adverse effects.'],'**Coordinate psychiatric and medical care urgently.**',['Treat dehydration, nutrition and other complications.','Plan continuation treatment after response rather than stopping care at the acute procedure.'],[['Severity','Life-threatening intake refusal'],['Rapid option','ECT'],['Whole plan','Medical stabilization and relapse prevention']],[DE],style='clinical_scenario')

q('For psychotic depression when pharmacotherapy is selected, which regimen is commonly recommended for specialist consideration?', 'An antidepressant combined with an antipsychotic',[
 ('A benzodiazepine alone','It may help selected symptoms but does not adequately treat both mood and psychosis.'),('A stimulant alone','This is not the routine evidence-based treatment and can worsen some symptoms.'),('Two antipsychotics without a depression-treatment plan as the default','Routine antipsychotic polypharmacy does not address the recommended combined approach.')],
 'Treat both components of the episode','**Psychotic depression often needs specialist combination treatment.**',['ECT is another important option, especially with urgency or inadequate response.','Patient preference and medication tolerability influence the plan.'],'**Monitor mood, psychosis, metabolic effects and function.**',['Reassess antipsychotic continuation after recovery with specialist input.','Do not stop a useful treatment abruptly without a relapse plan.'],[['Mood','Antidepressant component'],['Psychosis','Antipsychotic component'],['Alternative','ECT in appropriate circumstances']],[DE])

q('A patient with bipolar I depression needs a medication supported for acute bipolar depression. Which of the following is an appropriate established option?', 'Quetiapine',[
 ('Sertraline monotherapy','Antidepressant monotherapy is not recommended for bipolar I depression.'),('Lamotrigine as a rapidly titratable treatment for severe acute mania','Lamotrigine has different roles and must be titrated slowly.'),('Haloperidol selected primarily for its established antidepressant effect','It is useful for mania/psychosis but is not the corresponding first-line bipolar-depression option.')],
 'Evidence depends on the phase of bipolar illness','**A drug effective in mania is not automatically effective in bipolar depression.**',['Quetiapine has evidence for the depressive phase.','Choice also considers metabolic risk, sedation, prior response and the longer-term plan.'],'**Use a bipolar-specific shared treatment strategy.**',['Assess mixed features and switch history.','Avoid treating bipolar I depression as ordinary antidepressant-monotherapy depression.'],[['Acute depression','Phase-specific evidence'],['Acute mania','Different treatment set'],['Maintenance','Longer-term polarity prevention']],[CA,BP],style='clinical_scenario')

q('Which statement about lamotrigine in bipolar disorder is correct?', 'It has roles in depressive-phase and maintenance strategies but is not an established acute antimanic treatment',[
 ('It should be loaded rapidly to control severe mania overnight','Rapid escalation increases serious rash risk and it is not an acute antimanic drug.'),('It is interchangeable with lithium for every phase and outcome','Efficacy profiles and adverse effects differ.'),('It has no role in prevention of depressive recurrence','Depressive relapse prevention is an important use.')],
 'Polarity-specific efficacy guides drug selection','**Lamotrigine is more relevant to depressive burden than to acute mania control.**',['Titration must account for interacting drugs such as valproate.','Patients need clear advice about rash and systemic symptoms.'],'**Choose an effective antimanic agent for an acute manic episode.**',['Match maintenance treatment to the patient’s episode history.','Avoid abrupt unplanned switches of an effective regimen.'],[['Acute mania','Not established'],['Depressive burden','Relevant role'],['Safety','Slow titration and rash vigilance']],[CA,BP])

q('What is a major established role of lithium in bipolar disorder?', 'Long-term prevention of mood-episode recurrence, with acute antimanic efficacy as part of appropriate treatment',[
 ('Immediate reversal of opioid-related apnea','This is naloxone’s role.'),('A treatment requiring no drug-level or organ-function monitoring','Lithium has a narrow therapeutic range and important monitoring requirements.'),('A guarantee against every future mood episode','Relapse can still occur and ongoing review is needed.')],
 'Maintenance benefits require sustained safe use','**Lithium is a major mood-stabilizing treatment.**',['Selection considers prior response, renal function, interactions and preference.','Adherence, psychoeducation and relapse planning complement pharmacotherapy.'],'**Use regular levels and safety monitoring.**',['Teach hydration and illness/drug-interaction precautions.','Do not present observational suicide-risk benefits as an individual guarantee.'],[['Role','Acute mania and maintenance'],['Safety','Levels and organ monitoring'],['Outcome','Risk reduction, not certainty']],[NB,CA])

q('Which baseline and ongoing organ-function assessments are particularly important for lithium?', 'Renal function, thyroid function and calcium, alongside serum lithium levels and clinical monitoring',[
 ('Liver enzymes alone as a complete monitoring plan','Lithium safety prominently involves kidney, thyroid and calcium physiology.'),('A normal ECG alone without laboratory monitoring','ECG can be relevant but does not replace these assessments.'),('Only a blood count once at initiation','This does not monitor the principal ongoing risks.')],
 'Lithium monitoring extends beyond the serum concentration','**Kidney clearance and endocrine adverse effects affect long-term safety.**',['Assess weight, electrolytes and cardiac factors as appropriate.','Frequency increases with risk, interacting drugs or changing organ function.'],'**Review trends rather than isolated normal results.**',['Recheck after dose or interacting-medication changes.','Educate about tremor, GI symptoms, ataxia and other toxicity warnings.'],[['Kidney','Clearance and chronic risk'],['Thyroid/calcium','Endocrine effects'],['Drug level','Exposure and dose safety']],[NB,BP])

q('A patient with excellent bipolar control on lithium develops uncomplicated hypothyroidism. Which principle is most appropriate?', 'Assess and treat the thyroid disorder while reviewing lithium’s continuing benefit and overall risks',[
 ('Stop lithium abruptly in every case of raised TSH','Hypothyroidism can often be treated without discarding an effective mood stabilizer.'),('Ignore the abnormality because mood is stable','Untreated thyroid disease can cause symptoms and affect care.'),('Increase lithium specifically to correct the thyroid abnormality','This is not thyroid replacement therapy and can worsen risk.')],
 'An adverse effect does not always require immediate withdrawal','**Thyroid replacement can permit continued effective lithium treatment in suitable patients.**',['Confirm and characterize the abnormality.','Shared decision-making considers severity, alternatives and recurrence risk.'],'**Coordinate endocrine and psychiatric monitoring.**',['Reassess symptoms and thyroid response.','If lithium is changed, use a safe planned strategy rather than abrupt discontinuation.'],[['Finding','Hypothyroidism'],['Potential response','Thyroid treatment'],['Lithium decision','Individual benefit-risk review']],[NB,BP],style='clinical_scenario')

q('A patient develops a syndromal manic episode while taking antidepressant monotherapy. Which treatment principle is appropriate?', 'Review and stop or taper the antidepressant as clinically appropriate and initiate indicated antimanic treatment',[
 ('Increase the antidepressant to treat the increased energy','This can worsen destabilization.'),('Add a hypnotic only and continue the antidepressant unchanged as the complete plan','Sleep treatment alone does not address a full manic syndrome.'),('Wait for a depressive episode before treating the mania','Acute mania can create immediate risk and needs management.')],
 'A treatment-emergent switch requires a polarity review','**The current manic syndrome takes priority.**',['Assess substances, medical causes, severity and the longitudinal diagnosis.','Select an effective antipsychotic or mood-stabilizing strategy according to the presentation.'],'**Address sleep, behavior and safety with specialist care.**',['Consider supervised or inpatient care when risk or impairment warrants it.','Review future antidepressant use cautiously in a bipolar formulation.'],[['Current problem','Mania'],['Antidepressant','Reassess continuation'],['Treatment','Antimanic strategy']],[NB,CA],style='clinical_scenario')

q('A well patient taking lithium for recurrent bipolar disorder wants to stop because symptoms have resolved. Which advice is appropriate?', 'Discuss relapse risk and, if stopping is chosen, use a gradual monitored plan with early-warning and follow-up arrangements',[
 ('Stop immediately because remission proves the illness is cured','Remission may reflect effective maintenance treatment.'),('Never discuss alternatives because maintenance treatment removes the need for shared decisions','Preferences and adverse effects still matter.'),('Replace the entire regimen with antidepressant monotherapy regardless of past mania','That can destabilize bipolar I illness.')],
 'Maintenance treatment is evaluated during wellness','**Stopping effective treatment can increase relapse risk.**',['Abrupt lithium withdrawal is particularly undesirable.','Review episode severity, recurrence and the person’s reasons.'],'**Plan any change collaboratively and monitor for early recurrence.**',['Include sleep changes, energy and behavior in the warning plan.','Arrange rapid access to care if symptoms return.'],[['Remission','May be treatment-dependent'],['Stopping','Gradual and monitored'],['Prevention','Early-warning plan']],[NB,BP],style='clinical_scenario')

q('Within days of abruptly stopping paroxetine, a patient develops dizziness, nausea, vivid dreams and electric-shock sensations. Which diagnosis is most likely?', 'Antidepressant withdrawal syndrome',[
 ('Immediate proof of a new major depressive episode','The rapid onset and characteristic physical symptoms favor withdrawal.'),('Serotonin toxicity from an unchanged serotonergic burden','Symptoms followed cessation rather than a serotonergic increase and lack the characteristic neuromuscular syndrome.'),('A manic episode established by vivid dreams alone','There is no described elevated-energy syndrome.')],
 'Withdrawal can mimic or coexist with recurrence','**Shorter half-life antidepressants can cause symptoms after abrupt cessation.**',['Onset and physical symptoms help distinguish withdrawal from relapse.','Severity varies and some patients need a slower taper.'],'**Review a supervised symptom-guided reduction strategy.**',['Consider reinstatement and a slower taper when clinically indicated.','Do not dismiss symptoms as evidence of addiction or personal failure.'],[['Timing','Often soon after stopping'],['Clues','Dizziness/electric sensations'],['Management','Individualized taper and review']],[DE],style='clinical_scenario')

q('After remission from a first major depressive episode on an effective antidepressant, what is the usual continuation principle?', 'Continue effective treatment for at least several months after remission, commonly at least 6 months, with individualized review',[
 ('Stop as soon as the first symptom-free day occurs','Early stopping increases relapse risk.'),('Continue the same drug lifelong in every first episode without review','Duration depends on recurrence risk, severity, preferences and adverse effects.'),('Reduce treatment solely because work performance improves before full remission','Residual symptoms and relapse risk still need assessment.')],
 'Response and relapse prevention are different treatment phases','**Continuation helps consolidate recovery.**',['Recurrent, severe or high-risk illness may justify longer maintenance.','Psychological relapse-prevention strategies can also be useful.'],'**Review benefit, side effects and the eventual stopping plan.**',['Monitor for residual symptoms and new polarity clues.','Use gradual tapering when discontinuation is appropriate.'],[['Acute phase','Achieve remission'],['Continuation','Consolidate recovery'],['Maintenance','Individual recurrence-risk decision']],[DE])

if __name__=='__main__':finalize('Psychiatry',1,'Mood Disorders','psych-mood',rows,24)
